function calculateTotalPrice(items, taxRate) {
  return items.reduce((total, item) => total + item.price * (1 + taxRate), 0);
}

function getUserDisplayName(user) {
  if (!user) return 'Anonymous';
  if (!user.firstName) return user.email;
  return `${user.firstName} ${user.lastName}`.trim();
}

function parseApiResponse({ data, status, message }) {
  if (status !== 200) throw new Error(message);
  return data.map(({ id, name, createdAt }) => ({ id, name, createdAt }));
}

function validateForm(formData) {
  const errors = [];
  if (!formData.email || !formData.email.includes('@')) {
    errors.push('Email invalide');
  }
  if (!formData.password || formData.password.length < 8) {
    errors.push('Mot de passe trop court');
  }
  return { isValid: errors.length === 0, errors };
}

function buildMenuItems(routes, userRole) {
  const menuItems = [];
  for (const route of routes) {
    if (route.roles && route.roles.includes(userRole)) {
      menuItems.push({ label: route.label, path: route.path });
    }
  }
  return menuItems;
}

