function groupByCategory(productList) {
  const grouped = {};
  for (const product of productList) {
    const category = product.category || 'uncategorized';
    if (!grouped[category]) {
      grouped[category] = [];
    }
    grouped[category].push(product);
  }
  return grouped;
}
